settings.custom_liquid:
{%- liquid
  assign bc_col = nil
  assign bc_parent_col = nil

  assign bc_label = page_title | default: 'Pagina'

  assign bc_show_parent = false
  assign bc_parent_label = nil
  assign bc_parent_url = nil

  assign bc_show_mid = false
  assign bc_mid_label = nil
  assign bc_mid_url = nil

  assign mobile_back_col = nil

  if template.name == 'product' and product
    assign bc_label = product.title

    if product.metafields.custom.collectie.value != blank
      assign bc_col = product.metafields.custom.collectie.value
    elsif collection
      assign bc_col = collection
    endif

    if bc_col != blank
      assign bc_show_mid = true
      assign bc_mid_label = bc_col.title
      assign bc_mid_url = bc_col.url
      assign mobile_back_col = bc_col

      if bc_col.metafields.custom.parent_collectie.value != blank
        assign bc_parent_col = bc_col.metafields.custom.parent_collectie.value
      endif

      if bc_parent_col != blank
        assign bc_show_parent = true
        assign bc_parent_label = bc_parent_col.title
        assign bc_parent_url = bc_parent_col.url
      endif
    endif

  elsif template.name == 'collection' and collection
    assign bc_label = collection.title

    if collection.metafields.custom.parent_collectie.value != blank
      assign bc_parent_col = collection.metafields.custom.parent_collectie.value

      if bc_parent_col != blank
        assign bc_show_parent = true
        assign bc_parent_label = bc_parent_col.title
        assign bc_parent_url = bc_parent_col.url
      endif
    endif

  elsif template.name == 'page' and page
    assign bc_label = page.title

  elsif template.name == 'blog' and blog
    assign bc_label = blog.title

  elsif template.name == 'article' and article and blog
    assign bc_show_mid = true
    assign bc_mid_label = blog.title
    assign bc_mid_url = blog.url
    assign bc_label = article.title

  elsif template.name == 'search'
    assign bc_label = 'Search'

  elsif template.name == 'cart'
    assign bc_label = 'Cart'
  endif
-%}

{%- if template.name == 'product' and mobile_back_col != blank -%}
  <div class="rt-bc-mobile-back page-width">
    <a class="rt-bc-mobile-back__link" href="{{ mobile_back_col.url }}">
      <span class="rt-bc-mobile-back__icon" aria-hidden="true">
        <svg width="7" height="10" viewBox="0 0 7 10" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M1 9L5 5L1 1" stroke="currentColor" stroke-width="2"></path>
        </svg>
      </span>
      <span>{{ mobile_back_col.title }}</span>
    </a>
  </div>
{%- endif -%}

<div class="rt-bc-outer page-width">
  <nav class="rt-bc" aria-label="Breadcrumb">
    <ol class="rt-bc__list" role="list">

      <li class="rt-bc__item">
        <a class="rt-bc__link rt-bc__home" href="{{ routes.root_url }}" aria-label="Home">
          <span class="rt-bc__home-ico" aria-hidden="true">
            <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg" focusable="false" aria-hidden="true">
              <path d="M3.012,10.981,3,11H5v9a1,1,0,0,0,1,1H18a1,1,0,0,0,1-1V11h2a1,1,0,0,1,.555-1.832l-9-6a1,1,0,0,0-1.11,0l-9,6a1,1,0,0,0-.277,1.387A.98.98,0,0,0,3.012,10.981ZM10,14a1,1,0,0,1,1-1h2a1,1,0,0,1,1,1v5H10Z"></path>
            </svg>
          </span>
        </a>
      </li>

      <li class="rt-bc__sep" aria-hidden="true">
        <svg width="7" height="10" viewBox="0 0 7 10" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M1 9L5 5L1 1" stroke="currentColor" stroke-width="2"></path>
        </svg>
      </li>

      {%- if bc_show_parent and bc_parent_label and bc_parent_url -%}
        <li class="rt-bc__item">
          <a class="rt-bc__link" href="{{ bc_parent_url }}">{{ bc_parent_label }}</a>
        </li>
        <li class="rt-bc__sep" aria-hidden="true">
          <svg width="7" height="10" viewBox="0 0 7 10" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M1 9L5 5L1 1" stroke="currentColor" stroke-width="2"></path>
          </svg>
        </li>
      {%- endif -%}

      {%- if bc_show_mid and bc_mid_label and bc_mid_url -%}
        <li class="rt-bc__item">
          <a class="rt-bc__link" href="{{ bc_mid_url }}">{{ bc_mid_label }}</a>
        </li>
        <li class="rt-bc__sep" aria-hidden="true">
          <svg width="7" height="10" viewBox="0 0 7 10" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M1 9L5 5L1 1" stroke="currentColor" stroke-width="2"></path>
