{%- liquid
  assign threshold_eur = 100
  assign cutoff_hour = 17

  assign mf_vd = product.metafields.custom.volume_discounts
  assign vd = '{"tiers":[]}'
  if mf_vd != blank and mf_vd.value != blank
    if mf_vd.type == 'json'
