    else
      assign vd = mf_vd.value | strip
    endif
  endif
-%}

<div class="rt-shipfree rt-shipfree--dd"
     data-rt-shipfree
     data-threshold-eur="{{ threshold_eur }}"
     data-cutoff-hour="{{ cutoff_hour }}"
     data-timezone="Europe/Amsterdam">

  <button class="rt-shipfree__head" type="button" aria-expanded="false">
    <span class="rt-shipfree__text">Gratis verzending vanaf €{{ threshold_eur }}.</span>
    <svg class="rt-shipfree__chev" viewBox="0 0 12 12" width="14" height="14" aria-hidden="true" focusable="false">
      <path d="M2.2 4.3L6 8.1l3.8-3.8" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
    </svg>
  </button>

  <div class="rt-shipfree__panel" aria-hidden="true">
    <div class="rt-shipfree__panel-inner">
      <div class="rt-shipfree__delivery" data-rt-delivery-line>
        Verwachte levertijd: — (uiterlijk 3 werkdagen).
      </div>
    </div>
  </div>

  <script type="application/json" data-rt-volume-tiers>{{ vd }}</script>
  <script type="application/json" data-rt-variant-prices>
  [{%- for v in product.variants -%}{"id":{{ v.id }},"price":{{ v.price }} }{%- unless forloop.last -%},{%- endunless -%}{%- endfor -%}]
  </script>

  <style>
    .rt-shipfree {
      display: inline-flex !important;
      flex-direction: column !important;
      align-items: flex-start !important;
      gap: 0 !important;

      width: fit-content;
      max-width: 100%;

      padding: 4px 8px !important;
      border-radius: 8px;

      background: #EBF4FF !important;
      color: #002B5C !important;

      font-size: 14px !important;
      line-height: 1.2 !important;
      font-family: Overpass, sans-serif !important;
      font-weight: 500 !important;

      margin: 10px 0 !important;

      cursor: pointer;
      overflow: hidden;

      border: none !important;
      outline: none !important;
      box-shadow: none !important;

      transition: background 0.3s ease;
    }

    .rt-shipfree:hover { background: #d9eaff !important; }

    .rt-shipfree__head {
      display: flex !important;
      flex-direction: row !important;
      align-items: center !important;
      gap: 6px !important;

      width: 100% !important;
      padding: 0 !important;
      margin: 0 !important;

      background: transparent !important;
      color: inherit !important;
      font: inherit !important;
      text-align: left !important;

      cursor: pointer !important;

      border: none !important;
      outline: none !important;
    }

    .rt-shipfree__text{
      white-space: normal !important;
      flex: 0 0 auto;

      overflow-wrap: anywhere;
      word-break: normal;
      hyphens: auto;
    }

    .rt-shipfree__free{
      color: #74C200;
      font-weight: 700;
    }

    .rt-shipfree__chev{
      flex: 0 0 auto !important;
      transition: transform 250ms ease !important;
      transform-origin: 50% 50%;
    }

    .rt-shipfree__panel{
      display: block !important;
      width: 100%;
      max-width: 0;
      overflow: hidden;
      white-space: nowrap;
      opacity: 0;
      transition: max-width 250ms ease, opacity 250ms ease;
    }

    .rt-shipfree__panel-inner{
      max-height: 0;
      overflow: hidden;
      transition: max-height 250ms ease;
    }

    .rt-shipfree__delivery{
      padding-top: 8px;
      padding-bottom: 4px;

      font-size: 14px !important;
      line-height: 1.2 !important;
      color: inherit !important;
      font-family: inherit !important;
      font-weight: inherit !important;

      white-space: normal;
    }

    @media (max-width: 480px) {
      .rt-shipfree__head{
        display: grid !important;
        grid-template-columns: 1fr auto;
        column-gap: 6px;
        align-items: start !important;
      }

      .rt-shipfree__text{
        min-width: 0 !important;
        min-height: 0 !important;
      }

      .rt-shipfree.has-2lines .rt-shipfree__text{
        min-height: calc(1.2em * 2) !important;
      }

      .rt-shipfree__chev{
        margin-top: 2px;
        justify-self: end;
        align-self: start;
      }

      .rt-shipfree__panel{
        white-space: normal !important;
      }
    }
  </style>

  <script>
  (function(){
    var root = document.currentScript && document.currentScript.closest('[data-rt-shipfree]');
    if(!root) return;
    if(root.dataset.rtInited === "1") return;
    root.dataset.rtInited = "1";

    var thresholdEur = Number(root.getAttribute('data-threshold-eur') || 100);
    var cutoffHour   = Number(root.getAttribute('data-cutoff-hour') || 17);
    var timeZone     = root.getAttribute('data-timezone') || 'Europe/Amsterdam';

    var headBtn      = root.querySelector('.rt-shipfree__head');
    var textEl       = root.querySelector('.rt-shipfree__text');
    var panel        = root.querySelector('.rt-shipfree__panel');
    var panelInner   = root.querySelector('.rt-shipfree__panel-inner');
    var chev         = root.querySelector('.rt-shipfree__chev');
    var deliveryLine = root.querySelector('[data-rt-delivery-line]');

    var priceMap = new Map();
    try {
      var vp = JSON.parse(root.querySelector('script[data-rt-variant-prices]').textContent || '[]');
      vp.forEach(function(v){ priceMap.set(Number(v.id), Number(v.price)); });
    } catch(e){}

    var tiers = [];
    try {
      var raw = root.querySelector('script[data-rt-volume-tiers]').textContent || '{"tiers":[]}';
      var obj = JSON.parse(raw);
      if (typeof obj === 'string') obj = JSON.parse(obj);
      tiers = Array.isArray(obj.tiers) ? obj.tiers : [];
    } catch(e){
      tiers = [];
    }

    function normDisc(v){
      var n = Number(v);
      if(!isFinite(n)) return 0;
      if(n > 1) n = n / 100;
      if(n < 0) n = 0;
      if(n > 0.99) n = 0.99;
      return n;
    }

    tiers = tiers
      .map(function(t){
        return { min: Number(t.min), discount: normDisc(t.discount) };
      })
      .filter(function(t){
        return isFinite(t.min) && t.min >= 2 && t.discount > 0;
      })
      .sort(function(a,b){
        return a.min - b.min;
      });

    function discountForQty(qty){
      var d = 0;
      for(var i=0;i<tiers.length;i++){
        if(qty >= tiers[i].min) d = tiers[i].discount;
      }
      return d;
    }

    function getAmsterdamNowParts(){
      var now = new Date();

      var parts = new Intl.DateTimeFormat('en-GB', {
        timeZone: timeZone,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        hour12: false
      }).formatToParts(now);

      function val(type){
        var p = parts.find(function(x){ return x.type === type; });
        return p ? p.value : '';
      }

      var year  = Number(val('year'));
      var month = Number(val('month'));
      var day   = Number(val('day'));
      var hour  = Number(val('hour'));

      var amsterdamDateUtc = new Date(Date.UTC(year, month - 1, day, 12, 0, 0));
      var weekday = amsterdamDateUtc.getUTCDay(); // 0=Sun, 6=Sat

      return {
        year: year,
        month: month,
        day: day,
        hour: hour,
        weekday: weekday
      };
    }

    function amsterdamDatePlus(daysToAdd){
      var p = getAmsterdamNowParts();
      var d = new Date(Date.UTC(p.year, p.month - 1, p.day, 12, 0, 0));
      d.setUTCDate(d.getUTCDate() + daysToAdd);
      return d;
    }

    function formatAmsterdamWeekday(date){
      return new Intl.DateTimeFormat('nl-NL', {
        timeZone: timeZone,
        weekday: 'long'
      }).format(date).toUpperCase();
    }

    function getTimeInfo(){
      var p = getAmsterdamNowParts();
      return {
        wdNum: p.weekday, // 0=zon, 6=zat
        hr: p.hour
      };
    }

    function renderDelivery(){
      if(!deliveryLine) return;

      var t = getTimeInfo();
      var wd = t.wdNum;
      var hr = t.hr;
      var afterCutoff = hr >= cutoffHour;

      if (wd === 6 || wd === 0) {
        deliveryLine.textContent = 'Verwachte levertijd: 1–3 werkdagen.';
        return;
      }

      if (wd === 5 || (wd === 4 && afterCutoff)) {
        deliveryLine.textContent = 'Verwachte levertijd: 1–3 werkdagen.';
        return;
      }

      if (afterCutoff) {
        deliveryLine.textContent = 'Verwachte levertijd: MORGEN (uiterlijk 3 werkdagen).';
        return;
      }

      var tomorrow = amsterdamDatePlus(1);
      deliveryLine.textContent = 'Verwachte levertijd: ' + formatAmsterdamWeekday(tomorrow) + ' (uiterlijk 3 werkdagen).';
    }

    var FORM_SEL = 'form[action*="/cart/add"], form[action^="/cart/add"]';

    function formVisible(f){
      return !!(f && (f.offsetParent || f.getClientRects().length));
    }

    function findForm(){
      var direct = root.closest(FORM_SEL);
      if (direct) return direct;

      var node = root;
      while (node && node !== document.documentElement) {
        var forms = node.querySelectorAll(FORM_SEL);
        if (forms && forms.length) {
          for (var i=0;i<forms.length;i++) {
            if (formVisible(forms[i])) return forms[i];
          }
          return forms[0];
        }
        node = node.parentElement;
      }

      var all = document.querySelectorAll(FORM_SEL);
      for (var j=0;j<all.length;j++) {
        if (formVisible(all[j])) return all[j];
      }
      return all[0] || null;
    }

    function getQtyAndVariant(){
      var form = findForm();
      var idEl  = form ? form.querySelector('[name="id"]') : document.querySelector('[name="id"]');
      var qtyEl = form ? (form.querySelector('input[name="quantity"]') || form.querySelector('quantity-input input') || form.querySelector('input[type="number"]')) : null;

      var vid = idEl ? Number(idEl.value) : null;
      var qty = qtyEl ? Number(qtyEl.value) : 1;
      qty = (isFinite(qty) && qty > 0) ? Math.floor(qty) : 1;

      return { vid: vid, qty: qty };
    }

    function updateMessage(){
      if(!textEl) return;

      var vq = getQtyAndVariant();
      var vid = vq.vid;
      var qty = vq.qty;

      var basePrice = priceMap.get(Number(vid)) || 0;
      var disc = discountForQty(qty);

      var total = Math.round(basePrice * (1 - disc)) * qty;
      var thresholdCents = Math.round(thresholdEur * 100);

      var FREE = '<span class="rt-shipfree__free">GRATIS</span>';

      var t = getTimeInfo();
      var isTodayWindow = (t.wdNum !== 6 && t.wdNum !== 0 && t.hr < cutoffHour);

      if (total >= thresholdCents) {
        if (isTodayWindow) {
          textEl.innerHTML = 'Bestel je nu,<br>dan wordt je bestelling vandaag ' + FREE + ' verzonden.';
        } else {
          textEl.innerHTML = 'Elke werkdag vóór ' + cutoffHour + ':00<br>' + FREE + ' verzonden.';
        }
      } else {
        textEl.innerHTML = 'Gratis verzending vanaf €' + thresholdEur + '.';
      }

      root.classList.toggle('has-2lines', (textEl.innerHTML || '').indexOf('<br>') !== -1);
    }

    function setOpen(open){
      root.classList.toggle('is-open', !!open);

      if (headBtn) headBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
      if (panel) panel.setAttribute('aria-hidden', open ? 'false' : 'true');

      if (panel) {
        panel.style.maxWidth = open ? '800px' : '0px';
        panel.style.opacity  = open ? '1' : '0';
      }

      if (panelInner) {
        panelInner.style.maxHeight = open ? '150px' : '0px';
      }

      if (chev) {
        chev.style.transform = open ? 'rotate(180deg)' : 'rotate(0deg)';
      }
    }

    setOpen(false);

    root.addEventListener('click', function(e){
      e.stopPropagation();
      if (e.target && e.target.closest && e.target.closest('a')) return;
      setOpen(!root.classList.contains('is-open'));
    }, true);

    if (headBtn) {
      headBtn.addEventListener('click', function(e){
        e.preventDefault();
        e.stopPropagation();
        setOpen(!root.classList.contains('is-open'));
      }, true);
    }

    renderDelivery();
    updateMessage();

    function scheduleUpdate(){
      setTimeout(updateMessage, 20);
      setTimeout(updateMessage, 120);
      setTimeout(updateMessage, 250);
    }

    document.addEventListener('change', scheduleUpdate, true);
    document.addEventListener('input', scheduleUpdate, true);
    document.addEventListener('click', function(){
      setTimeout(updateMessage, 150);
    }, true);

    setInterval(renderDelivery, 60000);
  })();
  </script>
</div>

{%- liquid
  assign threshold_eur = 49
  assign threshold_cents = threshold_eur | times: 100
  assign qualifies_free_shipping = false

  if product.selected_or_first_available_variant and product.selected_or_first_available_variant.price >= threshold_cents
    assign qualifies_free_shipping = true
  endif

  assign has_out_of_stock_variant = false

  for variant in product.variants
    assign variant_stock = variant.inventory_quantity | default: 0

    if variant_stock <= 0
      assign has_out_of_stock_variant = true
    endif
  endfor

  assign now_ts = 'now' | date: '%s'
  assign current_hour = 'now' | date: '%H' | plus: 0
  assign current_wday = 'now' | date: '%w' | plus: 0

  assign tomorrow_ts = now_ts | plus: 86400
  assign tomorrow_wday = tomorrow_ts | date: '%w'

  assign tomorrow_name = ''
  case tomorrow_wday
    when '1'
      assign tomorrow_name = 'MAANDAG'
    when '2'
      assign tomorrow_name = 'DINSDAG'
    when '3'
      assign tomorrow_name = 'WOENSDAG'
    when '4'
      assign tomorrow_name = 'DONDERDAG'
    when '5'
      assign tomorrow_name = 'VRIJDAG'
    when '6'
      assign tomorrow_name = 'ZATERDAG'
    when '0'
      assign tomorrow_name = 'ZONDAG'
  endcase

  assign delivery_text = '1–3 werkdagen'

  if has_out_of_stock_variant
    assign delivery_text = '2–7 werkdagen'
  else
    if current_wday >= 1 and current_wday <= 5 and current_hour < 14
      assign delivery_text = tomorrow_name | append: ' (1-3 werkdagen)'
    else
      assign delivery_text = '1–3 werkdagen'
    endif
  endif
-%}

