  <script>
  (function(){
    var rootId = {{ uid | json }};
    var root = document.getElementById(rootId);
    if(!root || root.__rtGasket2dInit) return;
    root.__rtGasket2dInit = true;

    function extractNumber(v){
      if (v == null) return null;
      if (typeof v === "object") v = v.value || v.amount || v.number;
      if (typeof v === "number") return v;
      var m = String(v).trim().replace(",", ".").match(/(\d+(\.\d+)?)/);
      return m ? Number(m[1]) : null;
    }
    function fmt(n){ return n == null ? "" : String(Math.round(n * 10) / 10).replace(".", ","); }
    function setA(el,a,v){ if(el) el.setAttribute(a, String(v)); }

    var od = extractNumber({{ od_val | json }});
    var id = extractNumber({{ id_val | json }});
    var pcd = extractNumber({{ pcd_val | json }});
    var holeDia = extractNumber({{ hole_dia_val | json }});
    var holeCountNum = extractNumber({{ hole_count_val | json }});
    var holeCount = holeCountNum ? Math.max(1, Math.round(holeCountNum)) : null;
    var H = extractNumber({{ thk_val | json }});

    if(!od || od <= 0){ root.style.display = "none"; return; }

    var svg = root.querySelector("svg.rt-gasket2d__svg");
    var hasHoles = !!(pcd && holeDia && holeCount);
    var hasH = !!(H && H > 0);
    var cx = hasH ? 160 : 220, cy = 170;

    var rOuter = (!hasH && !hasHoles) ? 105 : 90;
    var scale = rOuter / (od / 2);
    var rInner = id ? (id / 2) * scale : 0;

    setA(root.querySelector(".outer-circle"), "cx", cx); setA(root.querySelector(".outer-circle"), "cy", cy); setA(root.querySelector(".outer-circle"), "r", rOuter);
    setA(root.querySelector(".inner-circle"), "cx", cx); setA(root.querySelector(".inner-circle"), "cy", cy); setA(root.querySelector(".inner-circle"), "r", rInner);
    setA(root.querySelector(".mask-outer"), "cx", cx); setA(root.querySelector(".mask-outer"), "cy", cy); setA(root.querySelector(".mask-outer"), "r", rOuter);
    setA(root.querySelector(".mask-inner"), "cx", cx); setA(root.querySelector(".mask-inner"), "cy", cy); setA(root.querySelector(".mask-inner"), "r", rInner);

    // OD Dims
    var yDimOD = 28;
    setA(root.querySelector(".od-ext-l"), "x1", cx-rOuter); setA(root.querySelector(".od-ext-l"), "x2", cx-rOuter); setA(root.querySelector(".od-ext-l"), "y1", yDimOD); setA(root.querySelector(".od-ext-l"), "y2", cy);
    setA(root.querySelector(".od-ext-r"), "x1", cx+rOuter); setA(root.querySelector(".od-ext-r"), "x2", cx+rOuter); setA(root.querySelector(".od-ext-r"), "y1", yDimOD); setA(root.querySelector(".od-ext-r"), "y2", cy);
    setA(root.querySelector(".od-line"), "x1", cx-rOuter); setA(root.querySelector(".od-line"), "x2", cx+rOuter); setA(root.querySelector(".od-line"), "y1", yDimOD); setA(root.querySelector(".od-line"), "y2", yDimOD);
    root.querySelector(".od-text").textContent = fmt(od) + " mm";
    setA(root.querySelector(".od-text"), "x", cx); setA(root.querySelector(".od-text"), "y", yDimOD - 10);

    // ID Dims
    var idDimGroup = root.querySelector(".id-dims");
    if(id && id > 0) {
      idDimGroup.style.display = "";
      var yDimID = 52;
      setA(root.querySelector(".id-ext-l"), "x1", cx-rInner); setA(root.querySelector(".id-ext-l"), "x2", cx-rInner); setA(root.querySelector(".id-ext-l"), "y1", yDimID); setA(root.querySelector(".id-ext-l"), "y2", cy);
      setA(root.querySelector(".id-ext-r"), "x1", cx+rInner); setA(root.querySelector(".id-ext-r"), "x2", cx+rInner); setA(root.querySelector(".id-ext-r"), "y1", yDimID); setA(root.querySelector(".id-ext-r"), "y2", cy);
      setA(root.querySelector(".id-line"), "x1", cx-rInner); setA(root.querySelector(".id-line"), "x2", cx+rInner); setA(root.querySelector(".id-line"), "y1", yDimID); setA(root.querySelector(".id-line"), "y2", yDimID);
      root.querySelector(".id-text").textContent = fmt(id) + " mm";
      setA(root.querySelector(".id-text"), "x", cx); setA(root.querySelector(".id-text"), "y", yDimID - 10);
    } else {
      idDimGroup.style.display = "none";
    }

    // Holes logic
    var pcdCircle = root.querySelector(".pcd-circle");
    setA(pcdCircle, "cx", cx); setA(pcdCircle, "cy", cy);
    var yDimPCD = null;
    if(hasHoles){
      var rPcd = (pcd/2)*scale, rHole = (holeDia/2)*scale;
      setA(pcdCircle, "r", rPcd);
      var mH = root.querySelector(".mask-holes"), oH = root.querySelector(".hole-outlines");
      mH.innerHTML = oH.innerHTML = "";
      for(var i=0; i<holeCount; i++){
        var a = (Math.PI/2) + i * (Math.PI*2/holeCount);
        var x = cx + rPcd * Math.cos(a), y = cy + rPcd * Math.sin(a);
        var cM = document.createElementNS("http://www.w3.org/2000/svg","circle");
        setA(cM,"cx",x); setA(cM,"cy",y); setA(cM,"r",rHole); cM.setAttribute("fill","black"); mH.appendChild(cM);
        var cO = document.createElementNS("http://www.w3.org/2000/svg","circle");
        setA(cO,"cx",x); setA(cO,"cy",y); setA(cO,"r",rHole); oH.appendChild(cO);
      }
      var yH = cy + rOuter + 42; yDimPCD = yH + 44;
      setA(root.querySelector(".hole-ext-l"),"x1",cx-rHole); setA(root.querySelector(".hole-ext-l"),"x2",cx-rHole); setA(root.querySelector(".hole-ext-l"),"y1",cy+rPcd); setA(root.querySelector(".hole-ext-l"),"y2",yH);
      setA(root.querySelector(".hole-ext-r"),"x1",cx+rHole); setA(root.querySelector(".hole-ext-r"),"x2",cx+rHole); setA(root.querySelector(".hole-ext-r"),"y1",cy+rPcd); setA(root.querySelector(".hole-ext-r"),"y2",yH);
      setA(root.querySelector(".hole-line"),"x1",cx-rHole); setA(root.querySelector(".hole-line"),"x2",cx+rHole); setA(root.querySelector(".hole-line"),"y1",yH); setA(root.querySelector(".hole-line"),"y2",yH);
      root.querySelector(".hole-text").textContent = "Ø "+fmt(holeDia)+" mm"; setA(root.querySelector(".hole-text"),"x",cx); setA(root.querySelector(".hole-text"),"y",yH+16);
      setA(root.querySelector(".pcd-ext-l"),"x1",cx-rPcd); setA(root.querySelector(".pcd-ext-l"),"x2",cx-rPcd); setA(root.querySelector(".pcd-ext-l"),"y1",yDimPCD); setA(root.querySelector(".pcd-ext-l"),"y2",cy);
      setA(root.querySelector(".pcd-ext-r"),"x1",cx+rPcd); setA(root.querySelector(".pcd-ext-r"),"x2",cx+rPcd); setA(root.querySelector(".pcd-ext-r"),"y1",yDimPCD); setA(root.querySelector(".pcd-ext-r"),"y2",cy);
      setA(root.querySelector(".pcd-line"),"x1",cx-rPcd); setA(root.querySelector(".pcd-line"),"x2",cx+rPcd); setA(root.querySelector(".pcd-line"),"y1",yDimPCD); setA(root.querySelector(".pcd-line"),"y2",yDimPCD);
      root.querySelector(".pcd-text").textContent = "PCD "+fmt(pcd)+" mm"; setA(root.querySelector(".pcd-text"),"x",cx); setA(root.querySelector(".pcd-text"),"y",yDimPCD+16);
    } else {
      ["pcd-ext-l","pcd-ext-r","pcd-line","pcd-text","hole-ext-l","hole-ext-r","hole-line","hole-text"].forEach(c => { if(root.querySelector("."+c)) root.querySelector("."+c).style.display="none"; });
    }

    // Thickness
    var thkG = root.querySelector(".thk");
    if(hasH && thkG){
      thkG.style.display = "";
      var x1 = cx + rOuter + 45, x2 = x1 + 10;
      setA(root.querySelector(".thk-left"),"x1",x1); setA(root.querySelector(".thk-left"),"x2",x1); setA(root.querySelector(".thk-left"),"y1",cy-rOuter); setA(root.querySelector(".thk-left"),"y2",cy+rOuter);
      setA(root.querySelector(".thk-right"),"x1",x2); setA(root.querySelector(".thk-right"),"x2",x2); setA(root.querySelector(".thk-right"),"y1",cy-rOuter); setA(root.querySelector(".thk-right"),"y2",cy+rOuter);
      setA(root.querySelector(".thk-top"),"x1",x1); setA(root.querySelector(".thk-top"),"x2",x2); setA(root.querySelector(".thk-top"),"y1",cy-rOuter); setA(root.querySelector(".thk-top"),"y2",cy-rOuter);
      setA(root.querySelector(".thk-bot"),"x1",x1); setA(root.querySelector(".thk-bot"),"x2",x2); setA(root.querySelector(".thk-bot"),"y1",cy+rOuter); setA(root.querySelector(".thk-bot"),"y2",cy+rOuter);
      if(id){
        setA(root.querySelector(".thk-id-top"),"x1",x1); setA(root.querySelector(".thk-id-top"),"x2",x2); setA(root.querySelector(".thk-id-top"),"y1",cy-rInner); setA(root.querySelector(".thk-id-top"),"y2",cy-rInner);
        setA(root.querySelector(".thk-id-bot"),"x1",x1); setA(root.querySelector(".thk-id-bot"),"x2",x2); setA(root.querySelector(".thk-id-bot"),"y1",cy+rInner); setA(root.querySelector(".thk-id-bot"),"y2",cy+rInner);
      }
      setA(root.querySelector(".thk-dim"),"x1",x1); setA(root.querySelector(".thk-dim"),"x2",x2); setA(root.querySelector(".thk-dim"),"y1",cy-rOuter-22); setA(root.querySelector(".thk-dim"),"y2",cy-rOuter-22);
      root.querySelector(".thk-text").textContent = fmt(H)+" mm"; setA(root.querySelector(".thk-text"),"x",(x1+x2)/2); setA(root.querySelector(".thk-text"),"y",cy-rOuter-32);
    }

    // Viewbox
    var xMin = (cx-rOuter)-22, xMax = (hasH ? cx+rOuter+45+10+30 : cx+rOuter+22);
    var yMin = yDimOD-22, yMax = hasHoles ? (yDimPCD+42) : (cy+rOuter+22);
    svg.setAttribute("viewBox", [xMin, yMin, xMax-xMin, yMax-yMin].join(" "));
  })();
  </script>
{%- endif -%}

{%- liquid
  assign p = product | default: closest.product

  assign col_ref = p.metafields.custom.collectie.value

  comment
    OPTION NAMING:
    - Change these to match your store exactly (case sensitive).
  endcomment
  assign opt_color_name = 'Color'
  assign opt_spec_name  = 'Specification'

  assign color_list = ''
  assign spec_first = ''

  for opt in p.options_with_values
    if opt.name == opt_color_name
      assign color_list = opt.values | join: ', '
    endif
    if opt.name == opt_spec_name
      assign spec_first = opt.values.first
    endif
  endfor

  assign has_rows = false
  if col_ref != blank or color_list != blank or spec_first != blank
    assign has_rows = true
  endif
-%}

{%- if has_rows -%}
  <section class="rt-specs" aria-label="Specificaties">
    <div class="page-width">
      <div class="rt-specs__tablewrap">
        <table class="rt-specs__table" role="table">
          <tbody>

            {%- if col_ref != blank -%}
              <tr>
                <th scope="row">Categorie</th>
                <td>
                  <a class="rt-specs__link" href="{{ col_ref.url }}">{{ col_ref.title }}</a>
                </td>
              </tr>
            {%- endif -%}

            {%- if color_list != blank -%}
              <tr>
                <th scope="row">Kleur</th>
                <td>{{ color_list }}</td>
              </tr>
            {%- endif -%}

            {%- if spec_first != blank -%}
              <tr>
                <th scope="row">Specificatie</th>
                <td>{{ spec_first }}</td>
              </tr>
            {%- endif -%}

          </tbody>
        </table>
      </div>
    </div>
  </section>

  <style>
    .rt-specs{ margin: 22px 0; }
    .rt-specs__table{
      width: 100%;
      border-collapse: collapse;
      table-layout: fixed;
      background: #fff;
      font-size: 14px;
      line-height: 1.35;
    }
    .rt-specs__table th,
    .rt-specs__table td{
      width: 50%;
      padding: 12px 14px;
      vertical-align: middle;
      text-align: left;
      color: inherit;
      word-break: break-word;
    }
    .rt-specs__table th{ font-weight: 600; }
    .rt-specs__table tbody tr:nth-child(odd){ background: #EDF0F2; }
    .rt-specs__link{
      color: inherit;
      text-decoration: underline;
      text-underline-offset: 2px;
    }
    .rt-specs__link:hover{ color:#003878; }
  </style>
{%- endif -%}

{%- comment -%}
  UNIVERSELE 2D SPECIFICATIES

  - Toont tabel als er specificaties zijn
  - Kiest automatisch tekeningstype:
      1) Gasket / ring als outer_diameter aanwezig is
      2) Rechthoek als length + width aanwezig zijn
      3) Anders geen SVG
  - Voorraad alleen getoond als inventory_management actief is én voorraad >= 25
  - Barcode en Artikelnummer staan onderaan
  - Aanzicht staat bovenaan in de tabel
  - Kenmerk/Waarde header heeft witte achtergrond
  - SVG-box heeft geen rand
  - Alleen de SVG blijft blauw, tabeltekst is zwart
  - Eenheden: expliciete mm/cm/m blijven behouden, zonder unit = Meter
  - M-schroefdraad notatie (bijv. M12):
      - Tabel toont "M12"
      - SVG tekent GEEN boutgaten (maatlijnen ook weggelaten)
  - Merk is klikbare link naar /collections/vendors
    (uitgezonderd RubberXL, Merkloos, Mijnwinkel, NoBrand)
  - Categorie = custom.collectie metafield
  - Hoofdcategorie = collectie.metafields.custom.parent_collectie
{%- endcomment -%}

{%- assign v = product.selected_or_first_available_variant -%}

{%- assign len_src        = v.metafields.custom.length              | default: product.metafields.custom.length -%}
{%- assign wid_src        = v.metafields.custom.width               | default: product.metafields.custom.width -%}
{%- assign hgt_src        = v.metafields.custom.height              | default: product.metafields.custom.height -%}
{%- assign thk_src        = v.metafields.custom.thickness           | default: product.metafields.custom.thickness -%}
{%- assign od_src         = v.metafields.custom.outer_diameter      | default: product.metafields.custom.outer_diameter -%}
{%- assign id_src         = v.metafields.custom.inner_diameter      | default: product.metafields.custom.inner_diameter -%}
{%- assign pcd_src        = v.metafields.custom.pitch_circle        | default: product.metafields.custom.pitch_circle -%}
{%- assign hole_dia_src   = v.metafields.custom.bolt_holes_diameter | default: product.metafields.custom.bolt_holes_diameter -%}
{%- assign hole_count_src = v.metafields.custom.bolt_holes_count    | default: product.metafields.custom.bolt_holes_count -%}
{%- assign collectie_src  = v.metafields.custom.collectie           | default: product.metafields.custom.collectie -%}

{%- assign len_val        = len_src.value        | default: len_src -%}
{%- assign wid_val        = wid_src.value        | default: wid_src -%}
{%- assign hgt_val        = hgt_src.value        | default: hgt_src -%}
{%- assign thk_val        = thk_src.value        | default: thk_src -%}
{%- assign od_val         = od_src.value         | default: od_src -%}
{%- assign id_val         = id_src.value         | default: id_src -%}
{%- assign pcd_val        = pcd_src.value        | default: pcd_src -%}
{%- assign hole_dia_val   = hole_dia_src.value   | default: hole_dia_src -%}
{%- assign hole_count_val = hole_count_src.value | default: hole_count_src -%}
{%- assign collectie_val  = collectie_src.value  | default: collectie_src -%}
{%- assign collectie_type = collectie_src.type   | default: '' -%}

{%- assign shape_list    = product.metafields.shopify.shape.value -%}
{%- assign material_list = product.metafields.shopify.material.value -%}
{%- assign color_list    = product.metafields.shopify['color-pattern'].value -%}

{%- assign sku_val          = v.sku -%}
{%- assign barcode_val      = v.barcode -%}
{%- assign product_type_val = product.type -%}
{%- assign vendor_val       = product.vendor | strip -%}

{%- assign vendor_lower = vendor_val | downcase | strip -%}
{%- assign show_vendor  = false -%}
{%- unless vendor_lower == blank
  or vendor_lower == 'rubberxl'
  or vendor_lower == 'merkloos'
  or vendor_lower == 'mijnwinkel'
  or vendor_lower == 'nobrand'
  or vendor_lower == 'no brand'
  or vendor_lower == 'merk loos'
-%}
  {%- assign show_vendor = true -%}
{%- endunless -%}

{%- assign inventory_managed = false -%}
{%- if v.inventory_management != blank -%}
  {%- assign inventory_managed = true -%}
{%- endif -%}
{%- assign inventory_qty = v.inventory_quantity | default: 0 -%}

{%- capture shape_text -%}
  {%- if shape_list != blank -%}
    {%- for it in shape_list -%}
      {%- assign label = it.system.title | default: it.title | default: it.name | default: it.system.handle | default: it.handle -%}
      {%- if label != blank -%}{{- label -}}{%- unless forloop.last -%}, {%- endunless -%}{%- endif -%}
    {%- endfor -%}
  {%- endif -%}
{%- endcapture -%}
{%- assign shape_text = shape_text | strip -%}

{%- capture material_text -%}
  {%- if material_list != blank -%}
    {%- for it in material_list -%}
      {%- assign label = it.system.title | default: it.title | default: it.name | default: it.system.handle | default: it.handle -%}
      {%- if label != blank -%}{{- label -}}{%- unless forloop.last -%}, {%- endunless -%}{%- endif -%}
    {%- endfor -%}
  {%- endif -%}
{%- endcapture -%}
{%- assign material_text = material_text | strip -%}

{%- capture color_text -%}
  {%- if color_list != blank -%}
    {%- for it in color_list -%}
      {%- assign raw = it.system.title | default: it.title | default: it.name | default: it.system.handle | default: it.handle -%}
      {%- if raw != blank -%}
        {%- assign part = raw | split: ' / ' | first -%}
        {%- assign part = part | split: ' - ' | first -%}
        {%- assign part = part | split: ' | ' | first -%}
        {%- assign part = part | split: ',' | first -%}
        {{- part | strip -}}{%- unless forloop.last -%}, {%- endunless -%}
      {%- endif -%}
    {%- endfor -%}
  {%- endif -%}
{%- endcapture -%}
{%- assign color_text = color_text | strip -%}

{%- capture collectie_html -%}
  {%- if collectie_val != blank -%}
    {%- if collectie_type contains 'list.' -%}
      {%- for it in collectie_val -%}
        {%- assign collectie_label = it.title | default: it.name | default: it.handle -%}
        {%- if it.url != blank and collectie_label != blank -%}
          <a class="rt-specdraw__category-link" href="{{ it.url }}">{{ collectie_label }}</a>{%- unless forloop.last -%}, {%- endunless -%}
        {%- elsif collectie_label != blank -%}
          {{ collectie_label }}{%- unless forloop.last -%}, {%- endunless -%}
        {%- endif -%}
      {%- endfor -%}
    {%- else -%}
      {%- assign collectie_label = collectie_val.title | default: collectie_val.name | default: collectie_val.handle | default: collectie_val -%}
      {%- assign collectie_url   = collectie_val.url -%}
      {%- if collectie_url != blank and collectie_label != blank -%}
        <a class="rt-specdraw__category-link" href="{{ collectie_url }}">{{ collectie_label }}</a>
      {%- elsif collectie_label != blank -%}
        {{ collectie_label }}
      {%- endif -%}
    {%- endif -%}
  {%- endif -%}
{%- endcapture -%}
{%- assign collectie_html = collectie_html | strip -%}

{%- assign bc_col = nil -%}
{%- if collectie_type contains 'list.' -%}
  {%- assign bc_col = collectie_val | first -%}
{%- else -%}
  {%- assign bc_col = collectie_val -%}
{%- endif -%}

{%- assign hoofdcategorie_col = nil -%}
{%- if bc_col != blank -%}
  {%- assign hoofdcategorie_col = bc_col.metafields.custom.parent_collectie.value -%}
{%- endif -%}

{%- capture hoofdcategorie_html -%}
  {%- if hoofdcategorie_col != blank -%}
    {%- assign hc_label = hoofdcategorie_col.title | default: hoofdcategorie_col.name | default: hoofdcategorie_col.handle -%}
    {%- assign hc_url   = hoofdcategorie_col.url -%}
    {%- if hc_url != blank and hc_label != blank -%}
      <a class="rt-specdraw__category-link" href="{{ hc_url }}">{{ hc_label }}</a>
    {%- elsif hc_label != blank -%}
      {{ hc_label }}
    {%- endif -%}
  {%- endif -%}
{%- endcapture -%}
{%- assign hoofdcategorie_html = hoofdcategorie_html | strip -%}

{%- capture vendor_html -%}
  {%- if show_vendor -%}
    <a class="rt-specdraw__category-link" href="/collections/vendors?q={{ vendor_val | url_encode }}">{{ vendor_val }}</a>
  {%- endif -%}
{%- endcapture -%}
{%- assign vendor_html = vendor_html | strip -%}

{%- assign drawing_type       = 'none' -%}
{%- assign drawing_view_label = '' -%}

{%- if od_val != blank -%}
  {%- assign drawing_type       = 'gasket' -%}
  {%- assign drawing_view_label = 'Bovenaanzicht' -%}
{%- elsif len_val != blank and wid_val != blank -%}
  {%- assign drawing_type       = 'rectangle' -%}
  {%- assign drawing_view_label = 'Bovenaanzicht' -%}
{%- endif -%}

{%- assign can_draw = false -%}
{%- if drawing_type != 'none' -%}
  {%- assign can_draw = true -%}
{%- endif -%}

{%- assign has_specs = false -%}
{%- if len_val != blank or wid_val != blank or hgt_val != blank or thk_val != blank
  or od_val != blank or id_val != blank or pcd_val != blank
  or hole_dia_val != blank or hole_count_val != blank
  or shape_text != blank or material_text != blank or color_text != blank
  or collectie_html != blank or hoofdcategorie_html != blank
  or product_type_val != blank or show_vendor
  or sku_val != blank or barcode_val != blank or inventory_managed
-%}
  {%- assign has_specs = true -%}
{%- endif -%}

{%- if has_specs or can_draw -%}
  {%- assign uid = 'rt-specdraw-' | append: product.id -%}

  <section id="{{ uid }}" class="rt-specdraw{% unless can_draw %} rt-specdraw--no-drawing{% endunless %}">
    <div class="rt-specdraw__wrap">

      {%- if has_specs -%}
        <div class="rt-specdraw__left">
          <div class="rt-specdraw__left-inner">
            <h3 class="rt-specdraw__title">Afmetingen & specificaties</h3>
            <table class="rt-specdraw__table" aria-label="Afmetingen en specificaties">
              <thead>
                <tr>
                  <th scope="col">Kenmerk</th>
                  <th scope="col">Waarde</th>
                </tr>
              </thead>
              <tbody>
                {%- if can_draw -%}
                  <tr class="rt-specdraw__view-row">
                    <td>Aanzicht 2D tekening</td>
                    <td>{{ drawing_view_label }}</td>
                  </tr>
                {%- endif -%}
                {%- if show_vendor -%}
                  <tr>
                    <td>Merk</td>
                    <td>{{ vendor_html }}</td>
                  </tr>
                {%- endif -%}
                {%- if len_val != blank -%}
                  <tr>
                    <td>Lengte</td>
                    <td><span class="rt-measure" data-raw='{{ len_val | json }}'></span></td>
                  </tr>
                {%- endif -%}
                {%- if wid_val != blank -%}
                  <tr>
                    <td>Breedte</td>
                    <td><span class="rt-measure" data-raw='{{ wid_val | json }}'></span></td>
                  </tr>
                {%- endif -%}
                {%- if hgt_val != blank -%}
                  <tr>
                    <td>Hoogte</td>
                    <td><span class="rt-measure" data-raw='{{ hgt_val | json }}'></span></td>
                  </tr>
                {%- endif -%}
                {%- if thk_val != blank -%}
                  <tr>
                    <td>Dikte</td>
                    <td><span class="rt-measure" data-raw='{{ thk_val | json }}'></span></td>
                  </tr>
                {%- endif -%}
                {%- if od_val != blank -%}
                  <tr>
                    <td>Buitendiameter (OD)</td>
                    <td><span class="rt-measure" data-raw='{{ od_val | json }}'></span></td>
                  </tr>
                {%- endif -%}
                {%- if id_val != blank -%}
                  <tr>
                    <td>Binnendiameter (ID)</td>
                    <td><span class="rt-measure" data-raw='{{ id_val | json }}'></span></td>
                  </tr>
                {%- endif -%}
                {%- if pcd_val != blank -%}
                  <tr>
                    <td>Steekcirkel (PCD)</td>
                    <td><span class="rt-measure" data-raw='{{ pcd_val | json }}'></span></td>
                  </tr>
                {%- endif -%}
                {%- if hole_dia_val != blank -%}
                  <tr>
                    <td>Boutgat</td>
                    <td><span class="rt-measure rt-measure--hole-dia" data-raw='{{ hole_dia_val | json }}'></span></td>
                  </tr>
                {%- endif -%}
                {%- if hole_count_val != blank -%}
                  <tr>
                    <td>Boutgaten</td>
                    <td>{{ hole_count_val }}</td>
                  </tr>
                {%- endif -%}
                {%- if shape_text != blank -%}
                  <tr>
                    <td>Vorm</td>
                    <td>{{ shape_text }}</td>
                  </tr>
                {%- endif -%}
                {%- if material_text != blank -%}
                  <tr>
                    <td>Materiaal</td>
                    <td>{{ material_text }}</td>
                  </tr>
                {%- endif -%}
                {%- if color_text != blank -%}
                  <tr>
                    <td>Kleur</td>
                    <td>{{ color_text }}</td>
                  </tr>
                {%- endif -%}
                {%- if hoofdcategorie_html != blank -%}
                  <tr>
                    <td>Hoofdcategorie</td>
                    <td>{{ hoofdcategorie_html }}</td>
                  </tr>
                {%- endif -%}
                {%- if collectie_html != blank -%}
                  <tr>
                    <td>Categorie</td>
                    <td>{{ collectie_html }}</td>
                  </tr>
                {%- endif -%}
                {%- if product_type_val != blank -%}
                  <tr>
                    <td>Producttype</td>
                    <td>{{ product_type_val }}</td>
                  </tr>
                {%- endif -%}
                {%- if inventory_managed and inventory_qty >= 25 -%}
                  <tr>
                    <td>Voorraad</td>
                    <td>{{ inventory_qty }} op voorraad</td>
                  </tr>
                {%- endif -%}
                {%- if barcode_val != blank -%}
                  <tr>
                    <td>Barcode</td>
                    <td>{{ barcode_val }}</td>
                  </tr>
                {%- endif -%}
                {%- if sku_val != blank -%}
                  <tr>
                    <td>Artikelnummer</td>
                    <td>{{ sku_val }}</td>
                  </tr>
                {%- endif -%}
              </tbody>
            </table>
          </div>
        </div>
      {%- endif -%}

      {%- if can_draw -%}
        <div class="rt-specdraw__right">
          <div class="rt-specdraw__right-inner">
            <div class="rt-specdraw__box" aria-label="2D tekening box">

              {%- if drawing_type == 'rectangle' -%}
                <svg class="rt-specdraw__svg rt-specdraw__svg--rectangle" viewBox="0 0 720 420" preserveAspectRatio="xMidYMid meet" role="img" aria-label="2D rechthoek met afmetingen">
                  <defs>
                    <marker id="{{ uid }}-arrow-rect" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse">
                      <path d="M 0 0 L 10 5 L 0 10 z" fill="currentColor"></path>
                    </marker>
                    <pattern id="{{ uid }}-hatch-rect" patternUnits="userSpaceOnUse" width="7" height="7" patternTransform="rotate(25)">
                      <line class="hatch-line" x1="0" y1="0" x2="0" y2="7"></line>
                    </pattern>
                  </defs>
                  <g class="shape" aria-hidden="true">
                    <rect class="rect-fill"   x="0" y="0" width="0" height="0"></rect>
                    <rect class="rect-hatch"  x="0" y="0" width="0" height="0" fill="url(#{{ uid }}-hatch-rect)"></rect>
                    <rect class="rect-stroke" x="0" y="0" width="0" height="0"></rect>
                  </g>
                  <g class="dims" aria-hidden="true">
                    <line class="dim-ext len-ext-l"></line>
                    <line class="dim-ext len-ext-r"></line>
                    <line class="dim-line len-line" marker-start="url(#{{ uid }}-arrow-rect)" marker-end="url(#{{ uid }}-arrow-rect)"></line>
                    <text class="dim-text len-text" text-anchor="middle"></text>
                    <line class="dim-ext wid-ext-t"></line>
                    <line class="dim-ext wid-ext-b"></line>
                    <line class="dim-line wid-line" marker-start="url(#{{ uid }}-arrow-rect)" marker-end="url(#{{ uid }}-arrow-rect)"></line>
                    <text class="dim-text wid-text" text-anchor="end"></text>
                  </g>
                </svg>
              {%- endif -%}

              {%- if drawing_type == 'gasket' -%}
                <svg class="rt-specdraw__svg rt-specdraw__svg--gasket" viewBox="0 0 440 520" preserveAspectRatio="xMidYMid meet" role="img" aria-label="2D pakking met afmetingen">
                  <defs>
                    <marker id="{{ uid }}-arrow-gasket" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse">
                      <path d="M 0 0 L 10 5 L 0 10 z" fill="currentColor"></path>
                    </marker>
                    <pattern id="{{ uid }}-hatch-gasket" patternUnits="userSpaceOnUse" width="7" height="7" patternTransform="rotate(25)">
                      <line class="hatch-line" x1="0" y1="0" x2="0" y2="7"></line>
                    </pattern>
                    <mask id="{{ uid }}-ringmask">
                      <rect width="100%" height="100%" fill="black"></rect>
                      <circle class="mask-outer" cx="160" cy="170" r="0" fill="white"></circle>
                      <circle class="mask-inner" cx="160" cy="170" r="0" fill="black"></circle>
                      <g class="mask-holes"></g>
                    </mask>
                  </defs>
                  <g class="gasket-shape" aria-hidden="true">
                    <circle class="outer-circle" cx="160" cy="170" r="0"></circle>
                    <circle class="inner-circle" cx="160" cy="170" r="0"></circle>
                    <rect class="ring-fill"  x="0" y="0" width="440" height="520" mask="url(#{{ uid }}-ringmask)"></rect>
                    <rect class="ring-hatch" x="0" y="0" width="440" height="520" fill="url(#{{ uid }}-hatch-gasket)" mask="url(#{{ uid }}-ringmask)"></rect>
                    <g class="hole-outlines"></g>
                    <circle class="pcd-circle" cx="160" cy="170" r="0"></circle>
                  </g>
                  <g class="gasket-dims" aria-hidden="true">
                    <line class="dim-ext od-ext-l"></line>
                    <line class="dim-ext od-ext-r"></line>
                    <line class="dim-line od-line" marker-start="url(#{{ uid }}-arrow-gasket)" marker-end="url(#{{ uid }}-arrow-gasket)"></line>
                    <text class="dim-text od-text" text-anchor="middle"></text>
                    <g class="id-dims">
                      <line class="dim-ext id-ext-l"></line>
                      <line class="dim-ext id-ext-r"></line>
                      <line class="dim-line id-line" marker-start="url(#{{ uid }}-arrow-gasket)" marker-end="url(#{{ uid }}-arrow-gasket)"></line>
                      <text class="dim-text id-text" text-anchor="middle"></text>
                    </g>
                    <line class="dim-ext hole-ext-l"></line>
                    <line class="dim-ext hole-ext-r"></line>
                    <line class="dim-line hole-line" marker-start="url(#{{ uid }}-arrow-gasket)" marker-end="url(#{{ uid }}-arrow-gasket)"></line>
                    <text class="dim-text hole-text" text-anchor="middle"></text>
                    <line class="dim-ext pcd-ext-l"></line>
                    <line class="dim-ext pcd-ext-r"></line>
                    <line class="dim-line pcd-line" marker-start="url(#{{ uid }}-arrow-gasket)" marker-end="url(#{{ uid }}-arrow-gasket)"></line>
                    <text class="dim-text pcd-text" text-anchor="middle"></text>
                    <g class="thk" style="display:none">
                      <line class="thk-vert thk-left"></line>
                      <line class="thk-vert thk-right"></line>
                      <line class="thk-h thk-top"></line>
                      <line class="thk-h thk-bot"></line>
                      <line class="thk-id-top"></line>
                      <line class="thk-id-bot"></line>
                      <line class="dim-line thk-dim" marker-start="url(#{{ uid }}-arrow-gasket)" marker-end="url(#{{ uid }}-arrow-gasket)"></line>
                      <text class="dim-text thk-text" text-anchor="middle"></text>
                    </g>
                  </g>
                </svg>
              {%- endif -%}

            </div>
          </div>
        </div>
      {%- endif -%}

    </div>
  </section>

  <style>
    #{{ uid }} {
      width: 100%;
      max-width: var(--page-width, 1200px);
      margin: 0 auto;
      padding: 24px 0;
      box-sizing: border-box;
      --rt-blue:  #003878;
      --rt-fill:  #EDF0F2;
      --rt-text:  #000000;
      --rt-hatch: #A0B2C9;
    }
    #{{ uid }} *, #{{ uid }} *::before, #{{ uid }} *::after { box-sizing: border-box; }
    #{{ uid }} .rt-specdraw__wrap {
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(0, 0.7fr);
      gap: 24px;
      align-items: stretch;
      width: 100%;
    }
    #{{ uid }}.rt-specdraw--no-drawing .rt-specdraw__wrap { grid-template-columns: minmax(0, 1fr); }
    #{{ uid }} .rt-specdraw__left {
      display: flex;
      align-items: center;
      min-height: clamp(320px, 44vh, 520px);
      min-width: 0;
    }
    #{{ uid }}.rt-specdraw--no-drawing .rt-specdraw__left { min-height: 0; }
    #{{ uid }} .rt-specdraw__left-inner { width: 100%; min-width: 0; }
    #{{ uid }} .rt-specdraw__title {
      margin: 0 0 16px;
      font-size: 24px;
      line-height: 1.1;
      color: var(--rt-blue);
      font-weight: 700;
    }
    #{{ uid }} .rt-specdraw__table {
      width: 100%;
      border-collapse: collapse;
      table-layout: fixed;
      background: #fff;
      font-size: 14px;
      line-height: 1.4;
      color: #000;
    }
    #{{ uid }} .rt-specdraw__table th,
    #{{ uid }} .rt-specdraw__table td {
      width: 50%;
      padding: 14px 16px;
      vertical-align: middle;
      text-align: left;
      border-bottom: 1px solid #ffffff;
      color: #000;
    }
    #{{ uid }} .rt-specdraw__table thead th { font-weight: 600; background: #ffffff; }
    #{{ uid }} .rt-specdraw__table tbody tr:nth-child(odd)  { background: #EDF0F2; }
    #{{ uid }} .rt-specdraw__table tbody tr:nth-child(even) { background: #ffffff; }
    #{{ uid }} .rt-specdraw__view-row td { font-weight: normal; }
    #{{ uid }} .rt-specdraw__category-link {
      color: #0075FA;
      text-decoration: underline;
      text-decoration-color: #0075FA;
      text-underline-offset: 2px;
      transition: text-decoration-color .2s ease, color .2s ease;
    }
    #{{ uid }} .rt-specdraw__category-link:hover { text-decoration-color: transparent; }
    #{{ uid }} .rt-specdraw__right {
      display: flex;
      align-items: center;
      justify-content: center;
      min-width: 0;
    }
    #{{ uid }} .rt-specdraw__right-inner { width: 100%; min-width: 0; }
    #{{ uid }} .rt-specdraw__box {
      width: 100%;
      height: clamp(320px, 44vh, 520px);
      max-width: 520px;
      border: 0;
      border-radius: 24px;
      background: #ffffff;
      display: flex;
      align-items: center;
      justify-content: center;
      overflow: hidden;
      min-width: 0;
      margin: 0 auto;
    }
    #{{ uid }} .rt-specdraw__svg {
      display: block;
      height: 100%;
      width: auto;
      max-width: 100%;
      color: var(--rt-blue);
      background: #ffffff;
      margin: 0 auto;
    }
    #{{ uid }} .rect-fill, #{{ uid }} .ring-fill { fill: var(--rt-fill); }
    #{{ uid }} .hatch-line {
      stroke: var(--rt-hatch);
      stroke-opacity: .45;
      stroke-width: 1;
      vector-effect: non-scaling-stroke;
      shape-rendering: geometricPrecision;
    }
    #{{ uid }} .rect-stroke,
    #{{ uid }} .outer-circle,
    #{{ uid }} .inner-circle {
      fill: none;
      stroke: var(--rt-blue);
      opacity: .72;
      stroke-width: 2;
      vector-effect: non-scaling-stroke;
      shape-rendering: geometricPrecision;
    }
    #{{ uid }} .hole-outlines circle {
      fill: #ffffff;
      stroke: var(--rt-blue);
      stroke-width: 1;
      opacity: .60;
      vector-effect: non-scaling-stroke;
      shape-rendering: geometricPrecision;
    }
    #{{ uid }} .pcd-circle {
      fill: none;
      stroke: var(--rt-blue);
      stroke-width: 1.25;
      opacity: .45;
      stroke-dasharray: 1 4;
      vector-effect: non-scaling-stroke;
      shape-rendering: geometricPrecision;
    }
    #{{ uid }} .dims .dim-line, #{{ uid }} .dims .dim-ext,
    #{{ uid }} .gasket-dims .dim-line, #{{ uid }} .gasket-dims .dim-ext {
      stroke: var(--rt-blue);
      opacity: .60;
      stroke-width: 1;
      vector-effect: non-scaling-stroke;
      shape-rendering: geometricPrecision;
    }
    #{{ uid }} .dims .dim-text, #{{ uid }} .gasket-dims .dim-text {
      fill: var(--rt-blue);
      opacity: .92;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: .2px;
      font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Arial;
      paint-order: stroke;
      stroke: #ffffff;
      stroke-width: 3px;
      stroke-linejoin: round;
    }
    #{{ uid }} .thk .thk-vert, #{{ uid }} .thk .thk-h {
      stroke: var(--rt-blue);
      opacity: .62;
      stroke-width: 1;
      vector-effect: non-scaling-stroke;
      shape-rendering: geometricPrecision;
    }
    #{{ uid }} .thk .thk-id-top, #{{ uid }} .thk .thk-id-bot {
      stroke: var(--rt-blue);
      opacity: .40;
      stroke-width: 1;
      stroke-dasharray: 1 4;
      vector-effect: non-scaling-stroke;
      shape-rendering: geometricPrecision;
    }
    @media (max-width: 900px) {
      #{{ uid }} .rt-specdraw__wrap { grid-template-columns: 1fr; gap: 12px; }
      #{{ uid }} .rt-specdraw__left { min-height: 0; align-items: flex-start; }
      #{{ uid }} .rt-specdraw__title { font-size: 26px; margin-bottom: 14px; }
      #{{ uid }} .rt-specdraw__box { max-width: none; height: clamp(240px, 38vh, 420px); }
    }
    @media (max-width: 767px) {
      #{{ uid }} .rt-specdraw__table th,
      #{{ uid }} .rt-specdraw__table td { padding: 12px; }
    }
  </style>

  <script>
    (function () {
      var rootId = {{ uid | json }};
      var root   = document.getElementById(rootId);
      if (!root || root.__rtSpecDrawBooted) return;
      root.__rtSpecDrawBooted = true;

      var drawingType = {{ drawing_type | json }};
      var canDraw     = {{ can_draw | json }};

      // Herkent "M12", "m10", "M16x1.5" etc.
      // Als TRUE: tabel toont "M12", SVG tekent GEEN boutgaten.
      function isMetricThread(raw) {
        if (raw == null) return false;
        var s = (typeof raw === 'object' ? String(raw.value != null ? raw.value : '') : String(raw)).trim();
        return /^m\d+(\.\d+)?(x\d+(\.\d+)?)?$/i.test(s);
      }

      // "m12" -> "M12"
      function normalizeThread(raw) {
        var s = (typeof raw === 'object' ? String(raw.value != null ? raw.value : '') : String(raw)).trim();
        return s.charAt(0).toUpperCase() + s.slice(1);
      }

      function normalizeUnit(unit) {
        if (!unit) return 'm';
        unit = String(unit).toLowerCase().trim();
        if (unit === 'mm' || unit === 'millimeter' || unit === 'millimeters') return 'mm';
        if (unit === 'cm' || unit === 'centimeter' || unit === 'centimeters') return 'cm';
        if (unit === 'm'  || unit === 'meter'      || unit === 'meters')      return 'm';
        return 'm';
      }

      function displayUnit(unit) {
        return normalizeUnit(unit) === 'm' ? 'Meter' : normalizeUnit(unit);
      }

      function parseMeasure(v) {
        if (v == null || v === '') return null;
        var unit = 'm', value = null;
        if (typeof v === 'object') {
          value = v.value != null ? v.value : v.amount != null ? v.amount : v.number != null ? v.number : null;
          if (v.unit != null) unit = normalizeUnit(v.unit);
        } else {
          value = v;
        }
        if (typeof value === 'number') return { value: value, unit: unit };
        var s = String(value).trim().replace(',', '.').toLowerCase();
        if      (s.indexOf('mm') > -1)                               unit = 'mm';
        else if (s.indexOf('cm') > -1)                               unit = 'cm';
        else if (s.match(/(^|\d|\s)m$/) || s.indexOf(' meter') > -1) unit = 'm';
        else    unit = unit || 'm';
        var m = s.match(/(\d+(\.\d+)?)/);
        if (!m) return null;
        return { value: Number(m[1]), unit: unit || 'm' };
      }

      function toMeters(measure) {
        if (!measure) return null;
        if (measure.unit === 'mm') return measure.value / 1000;
        if (measure.unit === 'cm') return measure.value / 100;
        return measure.value;
      }

      function fmtNumber(n) {
        if (n == null) return '';
        return String(Math.round(n * 1000) / 1000)
          .replace(/\.0+$/, '').replace(/(\.\d*[1-9])0+$/, '$1').replace('.', ',');
      }

      function fmtMeasure(measure) {
        if (!measure) return '';
        return fmtNumber(measure.value) + ' ' + displayUnit(measure.unit);
      }

      // Tabelweergave boutgat: M12 -> "M12", anders "O 12 mm"
      function fmtHoleDia(raw) {
        if (isMetricThread(raw)) return normalizeThread(raw);
        return '\u00D8 ' + fmtMeasure(parseMeasure(raw));
      }

      function extractNumber(v) {
        var m = parseMeasure(v);
        return m ? m.value : null;
      }

      function setA(el, a, v)      { if (el) el.setAttribute(a, String(v)); }
      function setAttrs(el, attrs) {
        if (!el) return;
        for (var k in attrs) el.setAttribute(k, attrs[k]);
      }

      function hydrateTableValues() {
        var nodes = root.querySelectorAll('.rt-measure[data-raw]');
        for (var i = 0; i < nodes.length; i++) {
          var el = nodes[i], raw;
          try   { raw = JSON.parse(el.getAttribute('data-raw')); }
          catch (e) { raw = el.getAttribute('data-raw'); }
          el.textContent = el.classList.contains('rt-measure--hole-dia')
            ? fmtHoleDia(raw)
            : fmtMeasure(parseMeasure(raw));
        }
      }

      function initRectangle() {
        if (root.__rtRectangleInit) return;
        root.__rtRectangleInit = true;
        var Lraw = {{ len_val | json }};
        var Wraw = {{ wid_val | json }};
        var Lm = toMeters(parseMeasure(Lraw));
        var Wm = toMeters(parseMeasure(Wraw));
        if (!(Lm > 0) || !(Wm > 0)) return;
        var svg = root.querySelector('.rt-specdraw__svg--rectangle');
        if (!svg) return;
        var padL = 120, padR = 40, padT = 90, padB = 70;
        var maxW = 720 - padL - padR, maxH = 420 - padT - padB;
        var sc = Math.min(maxW / Lm, maxH / Wm);
        var wPx = Math.max(10, Lm * sc), hPx = Math.max(10, Wm * sc);
        var x0 = padL + (maxW - wPx) / 2, y0 = padT + (maxH - hPx) / 2;
        ['.rect-fill', '.rect-hatch', '.rect-stroke'].forEach(function (s) {
          setAttrs(root.querySelector(s), { x: x0, y: y0, width: wPx, height: hPx });
        });
        var xL = x0, xR = x0 + wPx, yT = y0, yB = y0 + hPx;
        var yTop = yT - 28, xLeft = xL - 28;
        setAttrs(root.querySelector('.len-ext-l'), { x1: xL, x2: xL, y1: yTop, y2: yT });
        setAttrs(root.querySelector('.len-ext-r'), { x1: xR, x2: xR, y1: yTop, y2: yT });
        setAttrs(root.querySelector('.len-line'),  { x1: xL, x2: xR, y1: yTop, y2: yTop });
        var lenLabel = fmtMeasure(parseMeasure(Lraw));
        var lenTxt = root.querySelector('.len-text');
        setAttrs(lenTxt, { x: (xL + xR) / 2, y: yTop - 10 });
        lenTxt.textContent = lenLabel;
        setAttrs(root.querySelector('.wid-ext-t'), { x1: xLeft, x2: xL, y1: yT, y2: yT });
        setAttrs(root.querySelector('.wid-ext-b'), { x1: xLeft, x2: xL, y1: yB, y2: yB });
        setAttrs(root.querySelector('.wid-line'),  { x1: xLeft, x2: xLeft, y1: yT, y2: yB });
        var widLabel = fmtMeasure(parseMeasure(Wraw));
        var widTxt = root.querySelector('.wid-text');
        setAttrs(widTxt, { x: xLeft - 8, y: (yT + yB) / 2 + 4 });
        widTxt.textContent = widLabel;
        var txtW = (Math.max(lenLabel.length, widLabel.length) * 7) + 12;
        svg.setAttribute('viewBox', [
          xLeft - txtW - 14, yTop - 28,
          Math.max(10, xR + 22 - (xLeft - txtW - 14)),
          Math.max(10, yB + 22 - (yTop - 28))
        ].join(' '));
      }

      function initGasket() {
        if (root.__rtGasketInit) return;
        root.__rtGasketInit = true;

        var odRaw        = {{ od_val | json }};
        var idRaw        = {{ id_val | json }};
        var pcdRaw       = {{ pcd_val | json }};
        var holeDiaRaw   = {{ hole_dia_val | json }};
        var holeCountRaw = {{ hole_count_val | json }};
        var thkRaw       = {{ thk_val | json }};

        var od  = extractNumber(odRaw);
        var id  = extractNumber(idRaw);
        var pcd = extractNumber(pcdRaw);
        var H   = extractNumber(thkRaw);

        if (!od || od <= 0) return;

        // Als boutgat een M-maat is (M12 etc.) -> NIET tekenen in SVG
        var holeDiaIsThread = isMetricThread(holeDiaRaw);

        var holeDiaMm = null;
        if (!holeDiaIsThread && holeDiaRaw != null) {
          var hdm = parseMeasure(holeDiaRaw);
          if (hdm) {
            holeDiaMm = hdm.unit === 'mm' ? hdm.value
                      : hdm.unit === 'cm' ? hdm.value * 10
                      : hdm.value * 1000;
          }
        }

        var holeCount = null;
        if (holeCountRaw != null) {
          var hcStr = typeof holeCountRaw === 'object'
            ? String(holeCountRaw.value != null ? holeCountRaw.value : holeCountRaw)
            : String(holeCountRaw);
          var hcInt = parseInt(hcStr, 10);
          if (!isNaN(hcInt) && hcInt >= 1) holeCount = hcInt;
        }

        var svg = root.querySelector('.rt-specdraw__svg--gasket');
        if (!svg) return;

        // hasHoles is false bij M-notatie -> geen gaten in SVG
        var hasHoles = !holeDiaIsThread && !!(pcd && holeDiaMm && holeCount);
        var hasH     = !!(H && H > 0);

        var cx = hasH ? 160 : 220, cy = 170;
        var rOuter = (!hasH && !hasHoles) ? 105 : 90;
        var sc = rOuter / (od / 2);
        var rInner = id ? (id / 2) * sc : 0;

        setA(root.querySelector('.outer-circle'), 'cx', cx);
        setA(root.querySelector('.outer-circle'), 'cy', cy);
        setA(root.querySelector('.outer-circle'), 'r',  rOuter);
        setA(root.querySelector('.inner-circle'), 'cx', cx);
        setA(root.querySelector('.inner-circle'), 'cy', cy);
        setA(root.querySelector('.inner-circle'), 'r',  rInner);
        setA(root.querySelector('.mask-outer'), 'cx', cx);
        setA(root.querySelector('.mask-outer'), 'cy', cy);
        setA(root.querySelector('.mask-outer'), 'r',  rOuter);
        setA(root.querySelector('.mask-inner'), 'cx', cx);
        setA(root.querySelector('.mask-inner'), 'cy', cy);
        setA(root.querySelector('.mask-inner'), 'r',  rInner);

        var yDimOD = 28;
        setAttrs(root.querySelector('.od-ext-l'), { x1: cx - rOuter, x2: cx - rOuter, y1: yDimOD, y2: cy });
        setAttrs(root.querySelector('.od-ext-r'), { x1: cx + rOuter, x2: cx + rOuter, y1: yDimOD, y2: cy });
        setAttrs(root.querySelector('.od-line'),  { x1: cx - rOuter, x2: cx + rOuter, y1: yDimOD, y2: yDimOD });
        var odTxt = root.querySelector('.od-text');
        odTxt.textContent = fmtMeasure(parseMeasure(odRaw));
        setA(odTxt, 'x', cx); setA(odTxt, 'y', yDimOD - 10);

        var idGroup = root.querySelector('.id-dims');
        if (id && id > 0) {
          idGroup.style.display = '';
          var yDimID = 52;
          setAttrs(root.querySelector('.id-ext-l'), { x1: cx - rInner, x2: cx - rInner, y1: yDimID, y2: cy });
          setAttrs(root.querySelector('.id-ext-r'), { x1: cx + rInner, x2: cx + rInner, y1: yDimID, y2: cy });
          setAttrs(root.querySelector('.id-line'),  { x1: cx - rInner, x2: cx + rInner, y1: yDimID, y2: yDimID });
          var idTxt = root.querySelector('.id-text');
          idTxt.textContent = fmtMeasure(parseMeasure(idRaw));
          setA(idTxt, 'x', cx); setA(idTxt, 'y', yDimID - 10);
        } else {
          idGroup.style.display = 'none';
        }

        var pcdCircle = root.querySelector('.pcd-circle');
        setA(pcdCircle, 'cx', cx); setA(pcdCircle, 'cy', cy);

        var yDimPCD = null;

        if (hasHoles) {
          var rPcd  = (pcd / 2) * sc;
          var rHole = (holeDiaMm / 2) * sc;
          setA(pcdCircle, 'r', rPcd);
          var mH = root.querySelector('.mask-holes');
          var oH = root.querySelector('.hole-outlines');
          mH.innerHTML = ''; oH.innerHTML = '';
          for (var i = 0; i < holeCount; i++) {
            var ang = (Math.PI / 2) + i * (Math.PI * 2 / holeCount);
            var hx = cx + rPcd * Math.cos(ang), hy = cy + rPcd * Math.sin(ang);
            var cM = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
            setA(cM, 'cx', hx); setA(cM, 'cy', hy); setA(cM, 'r', rHole);
            cM.setAttribute('fill', 'black'); mH.appendChild(cM);
            var cO = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
            setA(cO, 'cx', hx); setA(cO, 'cy', hy); setA(cO, 'r', rHole);
            oH.appendChild(cO);
          }
          var yH = cy + rOuter + 42;
          yDimPCD = yH + 44;
          setAttrs(root.querySelector('.hole-ext-l'), { x1: cx - rHole, x2: cx - rHole, y1: cy + rPcd, y2: yH });
          setAttrs(root.querySelector('.hole-ext-r'), { x1: cx + rHole, x2: cx + rHole, y1: cy + rPcd, y2: yH });
          setAttrs(root.querySelector('.hole-line'),  { x1: cx - rHole, x2: cx + rHole, y1: yH, y2: yH });
          var holeTxt = root.querySelector('.hole-text');
          holeTxt.textContent = '\u00D8 ' + fmtMeasure(parseMeasure(holeDiaRaw));
          setA(holeTxt, 'x', cx); setA(holeTxt, 'y', yH + 16);
          setAttrs(root.querySelector('.pcd-ext-l'), { x1: cx - rPcd, x2: cx - rPcd, y1: yDimPCD, y2: cy });
          setAttrs(root.querySelector('.pcd-ext-r'), { x1: cx + rPcd, x2: cx + rPcd, y1: yDimPCD, y2: cy });
          setAttrs(root.querySelector('.pcd-line'),  { x1: cx - rPcd, x2: cx + rPcd, y1: yDimPCD, y2: yDimPCD });
          var pcdTxt = root.querySelector('.pcd-text');
          pcdTxt.textContent = 'PCD ' + fmtMeasure(parseMeasure(pcdRaw));
          setA(pcdTxt, 'x', cx); setA(pcdTxt, 'y', yDimPCD + 16);
        } else {
          // Geen boutgaten tekenen (ook niet bij M-notatie)
          setA(pcdCircle, 'r', 0);
          ['pcd-ext-l','pcd-ext-r','pcd-line','pcd-text',
           'hole-ext-l','hole-ext-r','hole-line','hole-text'].forEach(function (c) {
            var el = root.querySelector('.' + c);
            if (el) el.style.display = 'none';
          });
        }

        var thkG = root.querySelector('.thk');
        if (hasH && thkG) {
          thkG.style.display = '';
          var tx1 = cx + rOuter + 45, tx2 = tx1 + 10;
          setAttrs(root.querySelector('.thk-left'),  { x1: tx1, x2: tx1, y1: cy - rOuter, y2: cy + rOuter });
          setAttrs(root.querySelector('.thk-right'), { x1: tx2, x2: tx2, y1: cy - rOuter, y2: cy + rOuter });
          setAttrs(root.querySelector('.thk-top'),   { x1: tx1, x2: tx2, y1: cy - rOuter, y2: cy - rOuter });
          setAttrs(root.querySelector('.thk-bot'),   { x1: tx1, x2: tx2, y1: cy + rOuter, y2: cy + rOuter });
          if (id) {
            setAttrs(root.querySelector('.thk-id-top'), { x1: tx1, x2: tx2, y1: cy - rInner, y2: cy - rInner });
            setAttrs(root.querySelector('.thk-id-bot'), { x1: tx1, x2: tx2, y1: cy + rInner, y2: cy + rInner });
          }
          setAttrs(root.querySelector('.thk-dim'), { x1: tx1, x2: tx2, y1: cy - rOuter - 22, y2: cy - rOuter - 22 });
          var thkTxt = root.querySelector('.thk-text');
          thkTxt.textContent = fmtMeasure(parseMeasure(thkRaw));
          setA(thkTxt, 'x', (tx1 + tx2) / 2);
          setA(thkTxt, 'y', cy - rOuter - 32);
        }

        var xMin = (cx - rOuter) - 22;
        var xMax = hasH ? (cx + rOuter + 45 + 10 + 30) : (cx + rOuter + 22);
        var yMin = yDimOD - 22;
        var yMax = hasHoles ? (yDimPCD + 42) : (cy + rOuter + 22);
        svg.setAttribute('viewBox', [xMin, yMin, xMax - xMin, yMax - yMin].join(' '));
      }

      function initDrawing() {
        if (!canDraw) return;
        if (drawingType === 'rectangle') initRectangle();
        if (drawingType === 'gasket')    initGasket();
      }

      hydrateTableValues();
      if (!canDraw) return;

      if ('IntersectionObserver' in window) {
        var io = new IntersectionObserver(function (entries) {
          for (var i = 0; i < entries.length; i++) {
            if (entries[i].isIntersecting) { io.disconnect(); initDrawing(); break; }
          }
        }, { rootMargin: '200px 0px' });
        io.observe(root);
      } else if ('requestAnimationFrame' in window) {
        requestAnimationFrame(initDrawing);
      } else {
        initDrawing();
      }

    })();
  </script>
{%- endif -%}

{%- comment -%}
  DN table – Horizon aligned
  - Desktop: full Horizon width (theme controls)
  - Mobile: horizontal scroll
  - Clickable rows (test URL)
{%- endcomment -%}

{%- assign uid = 'rt-dn-table-' | append: product.id -%}
{%- assign row_url = '/products/test-kopie' -%}
{%- assign dns = '10,15,20,25,32,40,50,65,80,100' | split: ',' -%}

<section id="{{ uid }}" class="rt-dn">
  <h3 class="rt-dn__title">DN Dimensions</h3>

  <div class="rt-dn__scroll">
    <table class="rt-dn__table">
      <thead>
        <tr>
          <th>DN</th>
          <th>OD</th>
          <th>ID</th>
          <th>PCD</th>
          <th>Gaten</th>
          <th>Boutgat Ø</th>
        </tr>
      </thead>

      <tbody>
        {%- for dn in dns -%}
          <tr class="rt-dn__row" data-href="{{ row_url }}">
            <td><strong>DN{{ dn | strip }}</strong></td>
            <td>— mm</td>
            <td>— mm</td>
            <td>— mm</td>
            <td>—</td>
            <td>Ø — mm</td>
          </tr>
        {%- endfor -%}
      </tbody>
    </table>
  </div>
</section>

<style>
  /* Let Horizon control the width */
  #{{ uid }}.rt-dn{
    width: 100%;
    margin: 24px 0;
    padding: 24px 0; /* ✅ 24px top/bottom padding */
  }

  #{{ uid }} .rt-dn__title{
    margin: 0 0 24px;          /* ✅ 24px spacing under title */
    font-size: 32px;           /* ✅ 32px title */
    line-height: 1.1;
    font-weight: 750;
    color: #003878;
  }

  /* Scroll wrapper */
  #{{ uid }} .rt-dn__scroll{
    width: 100%;
    overflow-x: auto;
    overflow-y: hidden;
    -webkit-overflow-scrolling: touch;
  }

  /* Table */
  #{{ uid }} .rt-dn__table{
    width: 100%;
    border-collapse: collapse;
    font-size: 15px;
    background: #fff;
  }

  /* Lines */
  #{{ uid }} .rt-dn__table th,
  #{{ uid }} .rt-dn__table td{
    border: 1px solid #A0B2C9;
    padding: 12px 12px;
    text-align: center;
    white-space: nowrap;
  }

  /* Header */
  #{{ uid }} .rt-dn__table thead th{
    background: #003878;
    color: #fff;
    font-weight: 800;
  }

  /* Zebra */
  #{{ uid }} .rt-dn__table tbody tr:nth-child(even){
    background: #EDF0F2;
  }

  /* Hover */
  #{{ uid }} .rt-dn__row{
    cursor: pointer;
  }
  #{{ uid }} .rt-dn__row:hover td{
    color: #FF7300;
  }

  /* Mobile only: allow horizontal scroll */
  @media (max-width: 749px){
    #{{ uid }} .rt-dn__table{
      width: auto;
      min-width: 700px;
    }
  }
</style>

<script>
(function(){
  var root = document.getElementById({{ uid | json }});
  if(!root) return;
  if(root.__rtDnInit) return;
  root.__rtDnInit = true;

  root.addEventListener("click", function(e){
    var tr = e.target.closest("tr[data-href]");
    if(!tr) return;
    var href = tr.getAttribute("data-href");
    if(href) window.location.href = href;
  });
})();
</script>

{%- comment -%}
  COMBINED — Gasket Pro Visualizer
  - Tilt/angle from code #1: perspective(1500) rotateX(55deg) rotateZ(-2deg)
  - Size + texture + crisp thickness edge from code #2
  - Holes injected via JS (accurate)
{%- endcomment -%}

{%- assign v = product.selected_or_first_available_variant -%}

{%- assign od_val = v.metafields.custom.outer_diameter.value | default: product.metafields.custom.outer_diameter.value | default: 200 -%}
{%- assign id_val = v.metafields.custom.inner_diameter.value | default: product.metafields.custom.inner_diameter.value | default: 120 -%}
{%- assign pcd_val = v.metafields.custom.pitch_circle.value | default: product.metafields.custom.pitch_circle.value | default: 0 -%}

{%- comment -%} accept both naming variants {%- endcomment -%}
{%- assign hole_dia_val = v.metafields.custom.bolt_holes_diameter.value
  | default: product.metafields.custom.bolt_holes_diameter.value
  | default: v.metafields.custom.bolt_hole_diameter.value
  | default: product.metafields.custom.bolt_hole_diameter.value
  | default: 0 -%}

{%- assign hole_count_val = v.metafields.custom.bolt_holes_count.value
  | default: product.metafields.custom.bolt_holes_count.value
  | default: v.metafields.custom.bolt_hole_count.value
  | default: product.metafields.custom.bolt_hole_count.value
  | default: 0 -%}

{%- if od_val != blank and id_val != blank -%}
  {%- assign uid = 'gasket-combo-' | append: section.id | append: '-' | append: product.id -%}
  {%- assign wrap_id = uid | append: '-wrap' -%}
  {%- assign mask_id = uid | append: '-mask' -%}
  {%- assign thk_id  = uid | append: '-thickness' -%}
  {%- assign top_id  = uid | append: '-top' -%}

  <div id="{{ uid }}" class="gasket-visualizer-container">
    <div class="gasket-scene">
      <div class="gasket-3d-wrap" id="{{ wrap_id }}">
        <svg class="gasket-svg" viewBox="0 0 600 600" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Gasket preview">
          <defs>
            <mask id="{{ mask_id }}" maskUnits="userSpaceOnUse" maskContentUnits="userSpaceOnUse" x="0" y="0" width="600" height="600">
              <rect x="0" y="0" width="600" height="600" fill="black"></rect>
              <circle cx="300" cy="300" r="240" fill="white" class="svg-od"></circle>
              <circle cx="300" cy="300" r="140" fill="black" class="svg-id"></circle>
              <g class="svg-holes"></g>
            </mask>

            <!-- Crisp “thickness edge” (NO blur) -->
            <filter id="{{ thk_id }}" x="-30%" y="-30%" width="160%" height="160%">
              <feDropShadow dx="0" dy="10" stdDeviation="0" flood-color="rgba(0,0,0,0.28)"/>
              <feDropShadow dx="0" dy="6"  stdDeviation="0" flood-color="rgba(0,0,0,0.14)"/>
            </filter>

            <!-- Tiny top lift -->
            <filter id="{{ top_id }}" x="-10%" y="-10%" width="120%" height="120%">
              <feComponentTransfer>
                <feFuncR type="linear" slope="1.02" intercept="0"/>
                <feFuncG type="linear" slope="1.02" intercept="0"/>
                <feFuncB type="linear" slope="1.02" intercept="0"/>
              </feComponentTransfer>
            </filter>
          </defs>

          <!-- One group: thickness edge -->
          <g class="gasket-group" filter="url(#{{ thk_id }})">
            <image
              class="gasket-texture"
              href="https://cdn.shopify.com/s/files/1/0670/4168/9713/files/style_ifg-5500_gasket_sheet_md.jpg?v=1771748269"
              x="0" y="0"
              width="600" height="600"
              preserveAspectRatio="xMidYMid slice"
              mask="url(#{{ mask_id }})"
              filter="url(#{{ top_id }})"
            />
          </g>

          <!-- subtle rim highlight -->
          <circle cx="300" cy="300" r="240"
                  class="svg-od-border"
                  fill="none"
                  stroke="#ffffff"
                  stroke-width="1"
                  stroke-opacity="0.08"
                  mask="url(#{{ mask_id }})"></circle>
        </svg>
      </div>
    </div>
  </div>

  <style>
    /* Scoped */
    #{{ uid }}.gasket-visualizer-container{
      width: 100%;
      max-width: 600px;
      margin: 40px auto;
      aspect-ratio: 1 / 1;
      display: flex;
      align-items: center;
      justify-content: center;
      background: transparent;
    }

    #{{ uid }} .gasket-scene{
      position: relative;
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    /* USE ANGLE FROM CODE #1 */
    #{{ uid }} .gasket-3d-wrap{
      width: 100%;
      height: 100%;
      transform: perspective(1500px) rotateX(55deg) rotateZ(-2deg);
      transform-style: preserve-3d;
    }

    #{{ uid }} .gasket-svg{
      width: 100%;
      height: 100%;
      display: block;
      filter: none;
    }
  </style>

  <script>
    (function() {
      const root = document.getElementById({{ uid | json }});
      if (!root) return;
      if (root.__init) return;
      root.__init = true;

      function toNum(v){
        if (v == null) return 0;
        const s = String(v).trim().replace(",", ".");
        const m = s.match(/(\d+(\.\d+)?)/);
        return m ? Number(m[1]) : 0;
      }

      const od = toNum({{ od_val | json }});
      const id = toNum({{ id_val | json }});
      const pcd = toNum({{ pcd_val | json }});
      const hDia = toNum({{ hole_dia_val | json }});
      const hCount = Math.max(0, Math.round(toNum({{ hole_count_val | json }})));

      if (!od || !id || id <= 0 || od <= 0 || id >= od) {
        root.style.display = "none";
        return;
      }

      const baseR = 240;
      const scale = baseR / (od / 2);
      const center = 300;

      const rOuter = (od / 2) * scale;
      const rInner = (id / 2) * scale;

      const odNode = root.querySelector('.svg-od');
      const idNode = root.querySelector('.svg-id');
      const odBorder = root.querySelector('.svg-od-border');

      if (odNode) odNode.setAttribute('r', rOuter);
      if (idNode) idNode.setAttribute('r', rInner);
      if (odBorder) odBorder.setAttribute('r', rOuter);

      const holesGroup = root.querySelector('.svg-holes');
      if (holesGroup) holesGroup.innerHTML = "";

      const hasHoles = (hCount > 0 && pcd > 0 && hDia > 0);
      if (hasHoles && holesGroup) {
        const step = (Math.PI * 2) / hCount;
        const rPcd = (pcd / 2) * scale;
        const rHole = (hDia / 2) * scale;

        let html = "";
        for (let i = 0; i < hCount; i++) {
          const a = i * step - (Math.PI / 2);
          const x = center + Math.cos(a) * rPcd;
          const y = center + Math.sin(a) * rPcd;
          html += `<circle cx="${x}" cy="${y}" r="${rHole}" fill="black"></circle>`;
        }
        holesGroup.innerHTML = html;
      }
    })();
  </script>
{%- endif -%}
